from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _kernel(a_ref, b_ref, o_ref, acc):
    @pl.when(pl.program_id(2) == 0)
    def _():
        acc[...] = jnp.zeros_like(acc)
    acc[...] += jnp.dot(a_ref[...].astype(jnp.float32), b_ref[...].astype(jnp.float32), preferred_element_type=jnp.float32)

    @pl.when(pl.program_id(2) == pl.num_programs(2) - 1)
    def _():
        y = acc[...]
        y = y * 1.948
        o_ref[...] = y.astype(o_ref.dtype)


def workload(a, b):
    M, K = a.shape
    _, N = b.shape
    return pl.pallas_call(
        _kernel,
        out_shape=jax.ShapeDtypeStruct((M, N), a.dtype),
        grid=(M // 64, N // 64, K // 128),
        in_specs=[pl.BlockSpec((64, 128), lambda i, j, l: (i, l)), pl.BlockSpec((128, 64), lambda i, j, l: (l, j))],
        out_specs=pl.BlockSpec((64, 64), lambda i, j, l: (i, j)),
        scratch_shapes=[pltpu.VMEM((64, 64), jnp.float32)],
        compiler_params=pltpu.CompilerParams(dimension_semantics=("parallel", "parallel", "arbitrary")),
    )(a, b)

